    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000002\",\n  \"type\": \"https://trusttasks.org/spec/vtc/registry/sync-jobs/list/0.1#response\",\n  \"issuer\": \"did:example:community\",\n  \"recipient\": \"did:example:administrator\",\n  \"issuedAt\": \"2026-01-01T00:00:01Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"items\": [\n      {\n        \"jobId\": \"07c6c189-8272-4761-96e9-0ef869380665\",\n        \"kind\": \"publishMember\",\n        \"memberDid\": \"did:example:member\",\n        \"state\": \"failed\",\n        \"attempts\": 1,\n        \"lastError\": \"registry rejected registry/record/put: unsupportedType\",\n        \"createdAt\": \"2026-01-01T00:00:00Z\",\n        \"lastAttemptedAt\": \"2026-01-01T00:00:00Z\",\n        \"purgeDueAt\": \"2026-01-31T00:00:00Z\"\n      }\n    ]\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "Unknown state. The enum is the vocabulary a consumer can answer for; `complete` is not in it, because a completed job is deleted rather than listed.",
                "{\n  \"state\": \"complete\"\n}",
            ),
            (
                "Snake_case state — SPEC §4.10 makes wire enums lowerCamelCase, and `in_flight` is the spelling an implementation reading its own internal enum would send.",
                "{\n  \"state\": \"in_flight\"\n}",
            ),
            (
                "limit above the ceiling. 200 is the maximum the maintainer clamps to; a request for more must be refused rather than silently reduced, so a caller cannot believe it received a complete page.",
                "{\n  \"limit\": 500\n}",
            ),
            (
                "limit of zero. minimum 1 stops a page request that can only return nothing.",
                "{\n  \"limit\": 0\n}",
            ),
            (
                "Unknown top-level member — additionalProperties: false catches `memberDid`, which a caller might assume filters the list.",
                "{\n  \"memberDid\": \"did:example:member\"\n}",
            ),
            (
                "Bare/unnamespaced ext key — SPEC §4.5.1 requires every immediate child of ext to be reverse-DNS namespaced.",
                "{\n  \"ext\": {\n    \"page\": 2\n  }\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
